/* ---------- stockage durable ----------
   - Avec UPSTASH_REDIS_REST_URL + UPSTASH_REDIS_REST_TOKEN : tout est enregistré dans une base Upstash gratuite
     (comptes, sessions, messages, photos de profil...) et survit aux redémarrages de Render.
   - Sans : simple fichier sur le disque du serveur (effacé par Render gratuit à chaque redémarrage). */
const R_URL = (process.env.UPSTASH_REDIS_REST_URL || '').replace(/\/+$/, '');
const R_TOKEN = process.env.UPSTASH_REDIS_REST_TOKEN || '';
const USE_REDIS = !!(R_URL && R_TOKEN);
const DB_FILE = path.join(DATA_DIR, 'db.json');
const CHUNK = 200;                       // messages par bloc enregistré
const FILE_REDIS_MAX = 650 * 1024;       // les fichiers plus petits (photos) sont aussi gardés dans la base

let db = { users: {}, sessions: {}, contacts: {}, groups: {}, files: {}, push: {}, avatars: {}, vapid: null, messages: [], nextId: 1 };
let ready = false, loadError = '';
const lastSaved = new Map();

async function rcmd(cmds) {
  const r = await fetch(R_URL + '/pipeline', {
    method: 'POST', headers: { Authorization: 'Bearer ' + R_TOKEN, 'Content-Type': 'application/json' },
    body: JSON.stringify(cmds), signal: AbortSignal.timeout(20000)
  });
  const j = await r.json().catch(() => null);
  if (!r.ok || !Array.isArray(j)) throw new Error('Upstash ' + r.status + ' ' + JSON.stringify(j).slice(0, 200));
  for (const x of j) if (x && x.error) throw new Error('Upstash : ' + x.error);
  return j.map(x => x.result);
}

async function loadDb() {
  if (!USE_REDIS) {
    try { Object.assign(db, JSON.parse(fs.readFileSync(DB_FILE, 'utf8'))); } catch {}
  } else {
    const names = ['users', 'sessions', 'contacts', 'groups', 'files', 'push', 'meta', 'nmsg'];
    const vals = await rcmd(names.map(n => ['GET', 'd:' + n]));
    const o = {}; names.forEach((n, i) => o[n] = vals[i]);
    for (const k of ['users', 'sessions', 'contacts', 'groups', 'files', 'push']) if (o[k]) db[k] = JSON.parse(o[k]);
    if (o.meta) db.vapid = JSON.parse(o.meta).vapid || null;
    const n = parseInt(o.nmsg || '0', 10) || 0;
    const msgs = [];
    for (let i = 0; i < n; i += 40) {
      const idx = []; for (let j = i; j < Math.min(n, i + 40); j++) idx.push(j);
      const part = await rcmd(idx.map(j => ['GET', 'd:m:' + j]));
      for (const s of part) if (s) msgs.push(...JSON.parse(s));
    }
    db.messages = msgs;
  }
  db.nextId = db.messages.reduce((a, m) => Math.max(a, m.id), 0) + 1;
  for (const [t, s] of Object.entries(db.sessions)) if (Date.now() - s.ts > 365 * 864e5) delete db.sessions[t];
  if (!db.vapid) { db.vapid = genVapid(); save(); }
}

async function persist() {
  if (!USE_REDIS) {
    const tmp = DB_FILE + '.tmp';
    await fs.promises.writeFile(tmp, JSON.stringify(db));
    await fs.promises.rename(tmp, DB_FILE);
    return;
  }
  const out = {};
  for (const k of ['users', 'sessions', 'contacts', 'groups', 'files', 'push']) out['d:' + k] = JSON.stringify(db[k]);
  out['d:meta'] = JSON.stringify({ vapid: db.vapid });
  const n = Math.ceil(db.messages.length / CHUNK);
  for (let i = Math.max(0, n - 2); i < n; i++) out['d:m:' + i] = JSON.stringify(db.messages.slice(i * CHUNK, (i + 1) * CHUNK));
  out['d:nmsg'] = String(n);
  let batch = [], keys = [], size = 0;
  const run = async () => {
    if (!batch.length) return;
    await rcmd(batch);
    keys.forEach(([k, v]) => lastSaved.set(k, v));
    batch = []; keys = []; size = 0;
  };
  for (const [k, v] of Object.entries(out)) {
    if (lastSaved.get(k) === v) continue;
    if (size + v.length > 800 * 1024) await run();
    batch.push(['SET', k, v]); keys.push([k, v]); size += v.length;
  }
  await run();
}

let dirty = false, saving = false, saveTimer = null;
function save() { dirty = true; clearTimeout(saveTimer); saveTimer = setTimeout(flush, 300); }
async function flush() {
  if (saving || !ready) return;
  saving = true;
  try { while (dirty) { dirty = false; await persist(); } }
  catch (e) { console.error('Erreur enregistrement :', e.message); dirty = true; setTimeout(flush, 4000); }
  saving = false;
}
async function flushAll() {
  clearTimeout(saveTimer);
  for (let i = 0; i < 60 && (saving || dirty); i++) { if (!saving) await flush(); await sleep(100); }
}
for (const sig of ['SIGTERM', 'SIGINT']) process.on(sig, async () => { await flushAll(); process.exit(0); });

/* photos de profil et fichiers envoyés */
const avCache = new Map();
async function avGet(email) {
  if (!USE_REDIS) return db.avatars[email] || null;
  if (avCache.has(email)) return avCache.get(email);
  const [v] = await rcmd([['GET', 'a:' + uid(email)]]);
  if (v) avCache.set(email, v);
  return v || null;
}
async function avSet(email, b64) {
  if (!USE_REDIS) { db.avatars[email] = b64; save(); return; }
  await rcmd([['SET', 'a:' + uid(email), b64]]); avCache.set(email, b64);
}
async function avDel(email) {
  if (!USE_REDIS) { delete db.avatars[email]; save(); return; }
  await rcmd([['DEL', 'a:' + uid(email)]]); avCache.delete(email);
}
async function storeFile(id, buf) {
  await fs.promises.writeFile(path.join(UPLOAD_DIR, id), buf);
  if (USE_REDIS && buf.length <= FILE_REDIS_MAX) {
    try { await rcmd([['SET', 'f:' + id, buf.toString('base64')]]); db.files[id].kept = true; }
    catch (e) { console.error('Fichier non gardé :', e.message); }
  }
}
async function ensureFile(id) {
  const f = path.join(UPLOAD_DIR, id);
  if (fs.existsSync(f)) return true;
  if (!USE_REDIS || !db.files[id]?.kept) return false;
  try {
    const [v] = await rcmd([['GET', 'f:' + id]]);
    if (!v) return false;
    await fs.promises.writeFile(f, Buffer.from(v, 'base64')); return true;
  } catch { return false; }
}

/* ---------- utilitaires ---------- */
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const uid = e => crypto.createHash('sha256').update('discuter:' + e).digest('hex').slice(0, 16);
const mask = e => e.replace(/^(.{1,2}).*(@.*)$/, '$1***$2');
const picOf = u => u.avatarVer ? '/avatar/' + uid(u.email) + '?v=' + u.avatarVer : '';
const pub = u => ({ email: u.email, name: u.name, pic: picOf(u) });
let uidMap = null, uidCount = -1;
function emailByUid(id) {
  const n = Object.keys(db.users).length;
  if (!uidMap || n !== uidCount) { uidMap = new Map(Object.keys(db.users).map(e => [uid(e), e])); uidCount = n; }
  return uidMap.get(id);
}
const hashPw = (pw, salt) => new Promise((res, rej) => crypto.scrypt(pw, salt, 64, (e, k) => e ? rej(e) : res(k.toString('hex'))));
function newSession(email) {
  const t = crypto.randomBytes(32).toString('hex');
  db.sessions[t] = { email, ts: Date.now() };
  const mine = Object.entries(db.sessions).filter(([, s]) => s.email === email).sort((a, b) => a[1].ts - b[1].ts);
  while (mine.length > 12) delete db.sessions[mine.shift()[0]];
  save();
  return t;
}
function sessionUser(token) {
  const s = db.sessions[token];
  if (!s) return null;
  const u = db.users[s.email];
  if (!u) return null;
  if (Date.now() - s.ts > 864e5) { s.ts = Date.now(); save(); }   // la session se prolonge à chaque utilisation
  return u;
}
function tokenOf(req, url) {
  const h = req.headers.authorization || '';
  return h.startsWith('Bearer ') ? h.slice(7) : url.searchParams.get('token') || '';
}
function send(res, code, obj) {
  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(obj));
}
function readBody(req, limit) {
  return new Promise((resolve, reject) => {
    const chunks = []; let n = 0;
    req.on('data', c => {
      n += c.length;
      if (n > limit) { reject(Object.assign(new Error('Fichier trop gros'), { code: 413 })); req.destroy(); return; }
      chunks.push(c);
    });
    req.on('end', () => resolve(Buffer.concat(chunks)));
    req.on('error', reject);
  });
}
async function readJson(req) {
  const b = await readBody(req, 100 * 1024);
  try { return JSON.parse(b.toString('utf8') || '{}'); } catch { return {}; }
}
const hits = new Map();
function limited(req) {
  const ip = (req.headers['x-forwarded-for'] || '').split(',')[0].trim() || req.socket.remoteAddress;
  const now = Date.now();
  const a = (hits.get(ip) || []).filter(t => now - t < 60000);
  a.push(now); hits.set(ip, a);
  return a.length > 15;
}
function iceServers() {
  const list = [{ urls: 'stun:stun.l.google.com:19302' }, { urls: 'stun:stun1.l.google.com:19302' }];
  if (!process.env.TURN_URL) {
    list.push({ urls: ['turn:openrelay.metered.ca:80', 'turn:openrelay.metered.ca:443', 'turn:openrelay.metered.ca:443?transport=tcp'], username: 'openrelayproject', credential: 'openrelayproject' });
  } else {
    list.push({ urls: process.env.TURN_URL.split(',').map(s => s.trim()), username: process.env.TURN_USERNAME || '', credential: process.env.TURN_CREDENTIAL || '' });
  }
  return list;
}
const pubGroup = g => ({ id: g.id, name: g.name, owner: g.owner,
  members: g.members.filter(e => db.users[e]).map(e => ({ email: e, name: db.users[e].name, pic: picOf(db.users[e]) })) });
const groupsOf = email => Object.values(db.groups).filter(g => g.members.includes(email));
const isContact = (a, b) => (db.contacts[a] || []).includes(b);
function linkContacts(a, b) {
  for (const [x, y] of [[a, b], [b, a]]) {
    const l = db.contacts[x] || (db.contacts[x] = []);
    if (!l.includes(y)) l.push(y);
  }
  save();
}
function audience(email) {
  const s = new Set([email]);
  for (const c of db.contacts[email] || []) s.add(c);
  for (const g of groupsOf(email)) for (const m of g.members) s.add(m);
  return s;
}

/* ---------- notifications push (Web Push, chiffrement RFC 8291 / VAPID RFC 8292) ---------- */
/*PUSHCRYPTO-START*/
const b64u = b => Buffer.from(b).toString('base64url');
function genVapid() {
  const { publicKey, privateKey } = crypto.generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
  const pj = publicKey.export({ format: 'jwk' });
  const raw = Buffer.concat([Buffer.from([4]), Buffer.from(pj.x, 'base64url'), Buffer.from(pj.y, 'base64url')]);
  return { publicKey: b64u(raw), privateJwk: privateKey.export({ format: 'jwk' }) };
}
const hkdf = (ikm, salt, info, len) => Buffer.from(crypto.hkdfSync('sha256', ikm, salt, info, len));
function encryptPush(sub, data) {
  const ua = Buffer.from(sub.keys.p256dh, 'base64url'), auth = Buffer.from(sub.keys.auth, 'base64url');
  const ecdh = crypto.createECDH('prime256v1'); ecdh.generateKeys();
  const asPub = ecdh.getPublicKey(), secret = ecdh.computeSecret(ua), salt = crypto.randomBytes(16);
  const ikm = hkdf(secret, auth, Buffer.concat([Buffer.from('WebPush: info\0'), ua, asPub]), 32);
  const cek = hkdf(ikm, salt, Buffer.from('Content-Encoding: aes128gcm\0'), 16);
  const nonce = hkdf(ikm, salt, Buffer.from('Content-Encoding: nonce\0'), 12);
  const cipher = crypto.createCipheriv('aes-128-gcm', cek, nonce);
  const ct = Buffer.concat([cipher.update(Buffer.concat([data, Buffer.from([2])])), cipher.final(), cipher.getAuthTag()]);
  const head = Buffer.alloc(21); salt.copy(head, 0); head.writeUInt32BE(4096, 16); head[20] = 65;
  return Buffer.concat([head, asPub, ct]);
}
function vapidHeader(endpoint, vapid, subject) {
  const key = crypto.createPrivateKey({ key: vapid.privateJwk, format: 'jwk' });
  const h = b64u(JSON.stringify({ typ: 'JWT', alg: 'ES256' }));
  const c = b64u(JSON.stringify({ aud: new URL(endpoint).origin, exp: Math.floor(Date.now() / 1000) + 12 * 3600, sub: subject }));
  const sig = crypto.sign('sha256', Buffer.from(h + '.' + c), { key, dsaEncoding: 'ieee-p1363' });
  return `vapid t=${h}.${c}.${b64u(sig)}, k=${vapid.publicKey}`;
}
/*PUSHCRYPTO-END*/
async function sendPush(sub, payload) {
  const r = await fetch(sub.endpoint, {
    method: 'POST',
    headers: {
      'Content-Encoding': 'aes128gcm', 'Content-Type': 'application/octet-stream', TTL: '120', Urgency: 'high',
      Authorization: vapidHeader(sub.endpoint, db.vapid, process.env.VAPID_SUBJECT || 'mailto:contact@discuter.app')
    },
    body: encryptPush(sub, Buffer.from(JSON.stringify(payload))), signal: AbortSignal.timeout(10000)
  });
  return r.status;
}
const hasPush = e => (db.push[e] || []).length > 0;
const allHidden = email => { const s = socks.get(email); if (!s || !s.size) return true; for (const w of s) if (!w.hidden) return false; return true; };
function pushTo(email, payload) {
  if (!allHidden(email)) return;            // l'appli est ouverte à l'écran : pas besoin de notifier
  for (const sub of [...(db.push[email] || [])]) {
    sendPush(sub, payload).then(st => {
      if (st === 404 || st === 410) { db.push[email] = (db.push[email] || []).filter(x => x.endpoint !== sub.endpoint); save(); }
      else if (st >= 400) console.error('push refusé', st);
    }).catch(e => console.error('push', e.message));
  }
}
const previewOf = (kind, text) => kind === 'image' ? '📷 Photo' : kind === 'video' ? '🎬 Vidéo' : kind === 'file' ? '📎 Fichier' : String(text || '').slice(0, 140);

/* ---------- WebSocket : présence, messages, signalisation d'appel ---------- */
const socks = new Map();   // email -> Set<ws>
const busy = new Map();    // email -> { peer, ts }
const pendingOffers = new Map(); // appels vers quelqu'un hors ligne : livrés dès qu'il ouvre l'appli
const emit = (email, obj, except) => {
  const s = socks.get(email); if (!s) return;
  const data = JSON.stringify(obj);
  for (const w of s) if (w !== except && w.readyState === 1) w.send(data);
};
const isBusy = e => { const b = busy.get(e); return b && Date.now() - b.ts < 2 * 3600e3; };
function endCall(a) {
  const b = busy.get(a); if (!b) return null;
  busy.delete(a);
  if (busy.get(b.peer)?.peer === a) busy.delete(b.peer);
  return b.peer;
}
function announcePresence(email, online) {
  for (const c of db.contacts[email] || []) emit(c, { t: 'presence', email, online });
}
function storeMessage(from, to, kind, text, file) {
  const m = { id: db.nextId++, from, to, kind, text: text || '', file: file || null, ts: Date.now() };
  db.messages.push(m); save();
  const g = to.startsWith('g:') ? db.groups[to] : null;
  const targets = g ? g.members : [to, from];
  for (const t of new Set(targets)) emit(t, { t: 'msg', m });
  if (kind !== 'call') {
    const sender = db.users[from]?.name || from;
    for (const t of new Set(targets)) {
      if (t === from) continue;
      pushTo(t, g
        ? { title: g.name, body: sender + ' : ' + previewOf(kind, text), tag: 'c:' + g.id, key: g.id }
        : { title: sender, body: previewOf(kind, text), tag: 'c:' + from, key: from });
    }
  }
}

/* ---- appels de groupe (maillage : chaque participant est relié à chacun des autres) ---- */
const rooms = new Map();   // id du groupe -> { members:Set, video, starter, connectedAt }
function roomLeave(email, gid) {
  const r = rooms.get(gid);
  if (!r || !r.members.has(email)) return;
  r.members.delete(email);
  if (busy.get(email)?.peer === gid) busy.delete(email);
  for (const e of r.members) emit(e, { t: 'gleft', gid, email });
  if (!r.members.size) {
    rooms.delete(gid);
    const g = db.groups[gid];
    if (g) {
      for (const e of g.members) emit(e, { t: 'gend', gid });
      const d = r.connectedAt ? Math.round((Date.now() - r.connectedAt) / 1000) : 0;
      storeMessage(r.starter, gid, 'call', d ? `Appel de groupe · ${String(Math.floor(d / 60)).padStart(2, '0')}:${String(d % 60).padStart(2, '0')}` : 'Appel de groupe manqué');
    }
  }
}
const roomsLeaveAll = email => { for (const gid of [...rooms.keys()]) roomLeave(email, gid); };

function onWsMessage(ws, raw) {
  let m; try { m = JSON.parse(raw); } catch { return; }
  const me = ws.email;
  if (m.t === 'ping') { ws.send('{"t":"pong"}'); return; }
  if (m.t === 'vis') { ws.hidden = !!m.hidden; return; }
  if (m.t === 'gjoin') {
    const g = db.groups[m.gid];
    if (!g || !g.members.includes(me)) return;
    let r = rooms.get(g.id);
    if (r && r.members.has(me)) return;
    if (isBusy(me)) { emit(me, { t: 'gbusy' }); return; }
    const nameOf = e => db.users[e]?.name || e;
    if (!r) {
      r = { members: new Set([me]), video: !!m.video, starter: me, connectedAt: 0 };
      rooms.set(g.id, r); busy.set(me, { peer: g.id, ts: Date.now() });
      emit(me, { t: 'gpeers', gid: g.id, peers: [] });
      for (const e of g.members) if (e !== me && !isBusy(e)) {
        if (socks.has(e)) emit(e, { t: 'gring', gid: g.id, from: me, name: nameOf(me), video: r.video });
        pushTo(e, { title: '📞 Appel de groupe', body: `${nameOf(me)} appelle dans « ${g.name} »`, tag: 'gcall:' + g.id, key: g.id, call: true });
      }
    } else {
      const peers = [...r.members].map(e => ({ email: e, name: nameOf(e) }));
      r.members.add(me); busy.set(me, { peer: g.id, ts: Date.now() });
      if (!r.connectedAt) r.connectedAt = Date.now();
      emit(me, { t: 'gpeers', gid: g.id, peers });
    }
    return;
  }
  if (m.t === 'gleave') { roomLeave(me, String(m.gid || '')); return; }
  if (m.t === 'gsig') {
    const r = rooms.get(String(m.gid || ''));
    const dest = String(m.to || '');
    if (!r || !r.members.has(me) || !r.members.has(dest)) return;
    emit(dest, { t: 'gsig', gid: m.gid, from: me, kind: m.kind, data: m.data });
    return;
  }
  const to = typeof m.to === 'string' ? m.to : '';
  if (!to) return;
  if (to.startsWith('g:')) {            // message dans un groupe
    const g = db.groups[to];
    if (m.t !== 'msg' || !g || !g.members.includes(me)) return;
    const kind = ['text', 'image', 'video', 'file'].includes(m.kind) ? m.kind : 'text';
    let file = null;
    if (kind !== 'text') {
      const id = String(m.file?.url || '').replace('/uploads/', '');
      const f = db.files[id]; if (!f) return;
      file = { url: '/uploads/' + id, name: f.name, size: f.size, type: f.type };
    }
    const text = String(m.text || '').slice(0, 4000);
    if (kind === 'text' && !text.trim()) return;
    storeMessage(me, to, kind, text, file);
    return;
  }
  if (!isContact(me, to)) return;
  switch (m.t) {
    case 'msg': {
      const kind = ['text', 'image', 'video', 'file', 'call'].includes(m.kind) ? m.kind : 'text';
      let file = null;
      if (kind === 'image' || kind === 'video' || kind === 'file') {
        const id = String(m.file?.url || '').replace('/uploads/', '');
        const f = db.files[id];
        if (!f) return;
        file = { url: '/uploads/' + id, name: f.name, size: f.size, type: f.type };
      }
      const text = String(m.text || '').slice(0, 4000);
      if (kind === 'text' && !text.trim()) return;
      storeMessage(me, to, kind, text, file);
      break;
    }
    case 'offer': {
      if (isBusy(me) || isBusy(to)) { emit(me, { t: 'busy', from: to }); return; }
      const online = socks.has(to);
      if (!online && !hasPush(to)) { emit(me, { t: 'unavailable', from: to }); return; }
      busy.set(me, { peer: to, ts: Date.now() });
      busy.set(to, { peer: me, ts: Date.now() });
      if (online) emit(to, { t: 'offer', from: me, video: !!m.video, sdp: m.sdp });
      else pendingOffers.set(to, { from: me, video: !!m.video, sdp: m.sdp, ts: Date.now(), ice: [] });
      pushTo(to, { title: `📞 Appel ${m.video ? 'vidéo ' : ''}de ${db.users[me]?.name || me}`, body: "Touche pour répondre", tag: 'call:' + me, key: me, call: true });
      break;
    }
    case 'answer':
      if (busy.get(me)?.peer !== to) return;
      emit(me, { t: 'taken' }, ws);          // les autres appareils arrêtent de sonner
      emit(to, { t: 'answer', from: me, sdp: m.sdp });
      break;
    case 'ice': {
      if (busy.get(me)?.peer !== to) return;
      const po = pendingOffers.get(to);
      if (po && po.from === me && !socks.has(to)) { if (po.ice.length < 60) po.ice.push({ t: 'ice', from: me, candidate: m.candidate }); return; }
      emit(to, { t: 'ice', from: me, candidate: m.candidate });
      break;
    }
    case 'end':
    case 'reject':
      if (pendingOffers.get(to)?.from === me) pendingOffers.delete(to);
      if (busy.get(me)?.peer === to) endCall(me);
      emit(to, { t: m.t, from: me });
      emit(me, { t: 'taken' }, ws);
      break;
  }
}

function onWsConnection(ws, user) {
  ws.email = user.email; ws.alive = true; ws.hidden = false;
  const first = !socks.has(user.email);
  if (first) socks.set(user.email, new Set());
  socks.get(user.email).add(ws);
  ws.on('pong', () => { ws.alive = true; });
  ws.on('message', d => { try { onWsMessage(ws, d.toString()); } catch (e) { console.error(e); } });
  ws.on('close', () => {
    const s = socks.get(user.email); s.delete(ws);
    if (!s.size) {
      socks.delete(user.email);
      roomsLeaveAll(user.email);
      const peer = endCall(user.email);
      if (peer && !peer.startsWith('g:')) emit(peer, { t: 'end', from: user.email });
      announcePresence(user.email, false);
    }
  });
  const online = (db.contacts[user.email] || []).filter(c => socks.has(c));
  ws.send(JSON.stringify({ t: 'hello', online }));
  const po = pendingOffers.get(user.email);
  if (po) {
    pendingOffers.delete(user.email);
    if (Date.now() - po.ts < 40000 && busy.get(user.email)?.peer === po.from) {
      ws.send(JSON.stringify({ t: 'offer', from: po.from, video: po.video, sdp: po.sdp }));
      for (const i of po.ice) ws.send(JSON.stringify(i));
    } else endCall(user.email);
  }
  if (first) announcePresence(user.email, true);
}
setInterval(() => {   // appels restés sans réponse
  for (const [to, po] of pendingOffers) if (Date.now() - po.ts > 50000) { pendingOffers.delete(to); endCall(po.from); }
}, 10000);

/* ---------- HTTP ---------- */
const SAFE_INLINE = /^(image\/(png|jpe?g|gif|webp|avif|heic|heif|bmp)|video\/(mp4|webm|quicktime|ogg|x-m4v)|audio\/[a-z0-9.+-]+)$/i;

async function serveUpload(req, res, id) {
  const meta = db.files[id], file = path.join(UPLOAD_DIR, id);
  if (!meta || !(await ensureFile(id))) { res.writeHead(404); return res.end(); }
  const size = fs.statSync(file).size;
  const inline = SAFE_INLINE.test(meta.type);
  const headers = {
    'Content-Type': inline ? meta.type : 'application/octet-stream',
    'Content-Disposition': (inline ? 'inline' : 'attachment') + `; filename*=UTF-8''${encodeURIComponent(meta.name)}`,
    'X-Content-Type-Options': 'nosniff',
    'Accept-Ranges': 'bytes',
    'Cache-Control': 'private, max-age=86400'
  };
  const range = /^bytes=(\d*)-(\d*)$/.exec(req.headers.range || '');
  if (range) {
    let start = range[1] ? parseInt(range[1], 10) : 0;
    let end = range[2] ? parseInt(range[2], 10) : size - 1;
    if (!range[1] && range[2]) { start = Math.max(0, size - parseInt(range[2], 10)); end = size - 1; }
    end = Math.min(end, size - 1);
    if (start > end || start >= size) { res.writeHead(416, { 'Content-Range': `bytes */${size}` }); return res.end(); }
    res.writeHead(206, { ...headers, 'Content-Range': `bytes ${start}-${end}/${size}`, 'Content-Length': end - start + 1 });
    return fs.createReadStream(file, { start, end }).pipe(res);
  }
  res.writeHead(200, { ...headers, 'Content-Length': size });
  fs.createReadStream(file).pipe(res);
}

function broadcastProfile(user) {
  const msg = { t: 'profile', user: pub(user) };
  for (const e of audience(user.email)) emit(e, msg);
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://x');
    const p = url.pathname;
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Headers', 'Authorization, Content-Type');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    if (req.method === 'OPTIONS') { res.writeHead(204); return res.end(); }

    if (req.method === 'GET' && STATIC[p]) {
      const [name, type, cache] = STATIC[p];
      const buf = asset(name);
      if (!buf) { res.writeHead(404); return res.end(); }
      res.writeHead(200, { 'Content-Type': type, 'Cache-Control': cache, 'Content-Length': buf.length });
      return res.end(buf);
    }
    if (p === '/health') {
      return send(res, ready ? 200 : 503, { ok: ready, storage: USE_REDIS ? 'base de données Upstash (durable)' : 'fichier temporaire (effacé par Render à chaque redémarrage)',
        durable: USE_REDIS, users: Object.keys(db.users).length, messages: db.messages.length, error: loadError || undefined });
    }
    if (!ready) return send(res, 503, { error: 'Le serveur démarre, réessaie dans un instant…' });

    if (req.method === 'GET' && p.startsWith('/avatar/')) {
      const email = emailByUid(p.slice(8));
      const b64 = email && db.users[email]?.avatarVer ? await avGet(email) : null;
      if (!b64) { res.writeHead(404); return res.end(); }
      const buf = Buffer.from(b64, 'base64');
      res.writeHead(200, { 'Content-Type': 'image/jpeg', 'Cache-Control': 'public, max-age=86400', 'Content-Length': buf.length, 'X-Content-Type-Options': 'nosniff' });
      return res.end(buf);
    }
    if (req.method === 'GET' && p.startsWith('/uploads/')) {
      const id = p.slice(9);
      if (!/^[a-f0-9]{48}$/.test(id)) { res.writeHead(404); return res.end(); }
      return serveUpload(req, res, id);
    }
    if (req.method === 'GET' && p === '/api/config') {
      return send(res, 200, { googleClientId: GOOGLE_CLIENT_ID, iceServers: iceServers(), vapidPublicKey: db.vapid.publicKey });
    }

    /* --- comptes --- */
    if (req.method === 'POST' && (p === '/api/signup' || p === '/api/login' || p === '/api/google')) {
      if (limited(req)) return send(res, 429, { error: 'Trop de tentatives, réessaie dans une minute.' });
      const b = await readJson(req);

      if (p === '/api/signup') {
        const name = String(b.name || '').trim().slice(0, 40);
        const email = String(b.email || '').trim().toLowerCase();
        const password = String(b.password || '');
        if (!name) return send(res, 400, { error: 'Entre ton nom.' });
        if (!EMAIL_RE.test(email)) return send(res, 400, { error: 'Adresse e-mail invalide.' });
        if (password.length < 6 || password.length > 200) return send(res, 400, { error: 'Le mot de passe doit contenir au moins 6 caractères.' });
        if (db.users[email]) return send(res, 409, { error: 'Un compte existe déjà avec cet e-mail. Connecte-toi.' });
        const salt = crypto.randomBytes(16).toString('hex');
        db.users[email] = { email, name, salt, hash: await hashPw(password, salt), created: Date.now() };
        db.contacts[email] = db.contacts[email] || [];
        save();
        return send(res, 200, { token: newSession(email), user: pub(db.users[email]) });
      }

      if (p === '/api/login') {
        const email = String(b.email || '').trim().toLowerCase();
        const u = db.users[email];
        if (!u) return send(res, 401, { error: "Aucun compte avec cet e-mail. Crée un compte d'abord." });
        if (!u.hash) return send(res, 401, { error: 'Ce compte utilise Google. Clique sur « Continuer avec Google ».' });
        const h = Buffer.from(await hashPw(String(b.password || ''), u.salt), 'hex');
        if (!crypto.timingSafeEqual(h, Buffer.from(u.hash, 'hex'))) return send(res, 401, { error: 'Mot de passe incorrect.' });
        return send(res, 200, { token: newSession(email), user: pub(u) });
      }

      // Google
      if (!GOOGLE_CLIENT_ID) return send(res, 400, { error: "La connexion Google n'est pas configurée sur le serveur." });
      const r = await fetch('https://oauth2.googleapis.com/tokeninfo?id_token=' + encodeURIComponent(String(b.credential || '')));
      const g = await r.json().catch(() => ({}));
      if (!r.ok || g.aud !== GOOGLE_CLIENT_ID || String(g.email_verified) !== 'true' || !g.email) {
        return send(res, 401, { error: 'Connexion Google refusée.' });
      }
      const email = g.email.toLowerCase();
      if (!db.users[email]) {
        db.users[email] = { email, name: String(g.name || email.split('@')[0]).slice(0, 40), google: true, created: Date.now() };
        db.contacts[email] = db.contacts[email] || [];
        save();
      }
      return send(res, 200, { token: newSession(email), user: pub(db.users[email]) });
    }

    /* --- routes protégées --- */
    if (p.startsWith('/api/') || p === '/upload') {
      const user = sessionUser(tokenOf(req, url));
      if (!user) return send(res, 401, { error: 'Session expirée, reconnecte-toi.' });

      if (req.method === 'GET' && p === '/api/me') {
        const contacts = (db.contacts[user.email] || []).filter(e => db.users[e]).map(e => pub(db.users[e]));
        return send(res, 200, { user: pub(user), contacts, groups: groupsOf(user.email).map(pubGroup) });
      }
      if (req.method === 'GET' && p === '/api/history') {
        const mine = new Set(groupsOf(user.email).map(g => g.id));
        const list = db.messages.filter(m => m.from === user.email || m.to === user.email || mine.has(m.to)).slice(-3000);
        return send(res, 200, { messages: list });
      }
      if (req.method === 'POST' && p === '/api/profile') {
        const b = await readJson(req);
        const name = String(b.name || '').trim().slice(0, 40);
        if (!name) return send(res, 400, { error: 'Le nom ne peut pas être vide.' });
        user.name = name; save(); broadcastProfile(user);
        return send(res, 200, { user: pub(user) });
      }
      if (req.method === 'POST' && p === '/api/avatar') {
        const buf = await readBody(req, 250 * 1024);
        if (buf.length < 100 || buf[0] !== 0xff || buf[1] !== 0xd8) return send(res, 400, { error: 'Image invalide (JPEG attendu).' });
        await avSet(user.email, buf.toString('base64'));
        user.avatarVer = Date.now(); save(); broadcastProfile(user);
        return send(res, 200, { user: pub(user) });
      }
      if (req.method === 'POST' && p === '/api/avatar/remove') {
        await avDel(user.email); delete user.avatarVer; save(); broadcastProfile(user);
        return send(res, 200, { user: pub(user) });
      }
      if (req.method === 'POST' && p === '/api/push') {
        const b = await readJson(req), s = b.sub || {};
        if (!(/^https:\/\//.test(String(s.endpoint || '')) || (process.env.ALLOW_HTTP_PUSH && /^http:\/\/localhost/.test(String(s.endpoint || '')))) || !s.keys?.p256dh || !s.keys?.auth) return send(res, 400, { error: 'Abonnement invalide.' });
        const list = (db.push[user.email] || []).filter(x => x.endpoint !== s.endpoint);
        list.push({ endpoint: String(s.endpoint), keys: { p256dh: String(s.keys.p256dh), auth: String(s.keys.auth) }, ts: Date.now() });
        db.push[user.email] = list.slice(-6); save();
        return send(res, 200, { ok: true });
      }
      if (req.method === 'POST' && p === '/api/push/remove') {
        const b = await readJson(req);
        db.push[user.email] = (db.push[user.email] || []).filter(x => x.endpoint !== b.endpoint); save();
        return send(res, 200, { ok: true });
      }
      if (req.method === 'POST' && p === '/api/groups') {
        const b = await readJson(req);
        const name = String(b.name || '').trim().slice(0, 40);
        if (!name) return send(res, 400, { error: 'Donne un nom au groupe.' });
        const ids = [...new Set((Array.isArray(b.members) ? b.members : []).map(e => String(e).toLowerCase()))]
          .filter(e => e !== user.email && isContact(user.email, e) && db.users[e]).slice(0, 49);
        if (!ids.length) return send(res, 400, { error: 'Choisis au moins un ami.' });
        const id = 'g:' + crypto.randomBytes(8).toString('hex');
        db.groups[id] = { id, name, owner: user.email, members: [user.email, ...ids], created: Date.now() };
        save();
        const g = pubGroup(db.groups[id]);
        for (const e of ids) {
          emit(e, { t: 'group', group: g, by: user.name });
          pushTo(e, { title: 'Nouveau groupe', body: `${user.name} t'a ajouté au groupe « ${name} »`, tag: 'g:' + id, key: id });
        }
        return send(res, 200, { group: g });
      }
      if (req.method === 'GET' && p === '/api/users') {
        const have = new Set(db.contacts[user.email] || []);
        const users = Object.values(db.users).filter(u => u.email !== user.email && !have.has(u.email))
          .sort((a, b) => a.name.localeCompare(b.name, 'fr')).slice(0, 1000)
          .map(u => ({ id: uid(u.email), name: u.name, email: mask(u.email), pic: picOf(u), online: socks.has(u.email) }));
        return send(res, 200, { users });
      }
      if (req.method === 'POST' && p === '/api/contacts') {
        const b = await readJson(req);
        let email = String(b.email || '').trim().toLowerCase();
        if (b.id) { const f = emailByUid(String(b.id)); if (f) email = f; }
        if (email === user.email) return send(res, 400, { error: "C'est ton propre e-mail." });
        const target = db.users[email];
        if (!target) return send(res, 404, { error: "Cette personne n'a pas encore de compte." });
        linkContacts(user.email, email);
        emit(email, { t: 'contact', contact: pub(user), online: socks.has(user.email) });
        return send(res, 200, { contact: pub(target), online: socks.has(email) });
      }
      if (req.method === 'POST' && p === '/api/logout') {
        delete db.sessions[tokenOf(req, url)]; save();
        return send(res, 200, { ok: true });
      }
      if (req.method === 'POST' && p === '/upload') {
        const buf = await readBody(req, MAX_UPLOAD);
        if (!buf.length) return send(res, 400, { error: 'Fichier vide.' });
        const id = crypto.randomBytes(24).toString('hex');
        const name = path.basename(String(url.searchParams.get('name') || 'fichier')).slice(0, 120) || 'fichier';
        const type = String(url.searchParams.get('type') || req.headers['content-type'] || 'application/octet-stream').slice(0, 100);
        db.files[id] = { name, type, size: buf.length, owner: user.email };
        await storeFile(id, buf);
        save();
        return send(res, 200, { url: '/uploads/' + id, name, type, size: buf.length });
      }
    }
    send(res, 404, { error: 'Introuvable' });
  } catch (e) {
    if (e && e.code === 413) return send(res, 413, { error: 'Fichier trop gros.' });
    console.error(e);
    if (!res.headersSent) send(res, 500, { error: 'Erreur serveur' });
  }
});

const wss = new WebSocketServer({ noServer: true, maxPayload: 256 * 1024 });
server.on('upgrade', (req, socket, head) => {
  const url = new URL(req.url, 'http://x');
  const user = ready && url.pathname === '/ws' ? sessionUser(url.searchParams.get('token') || '') : null;
  if (!user) { socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n'); return socket.destroy(); }
  wss.handleUpgrade(req, socket, head, ws => onWsConnection(ws, user));
});
// ping régulier : garde la connexion vivante derrière le proxy de Render et nettoie les connexions mortes
setInterval(() => {
  for (const set of socks.values()) for (const ws of set) {
    if (!ws.alive) { ws.terminate(); continue; }
    ws.alive = false; ws.ping();
  }
}, 25000);

server.listen(PORT, '0.0.0.0', () => console.log('Discuter écoute sur le port ' + PORT + ' · stockage : ' + (USE_REDIS ? 'Upstash' : 'fichier')));
(async () => {
  for (let i = 1; ; i++) {
    try {
      await loadDb(); ready = true; loadError = '';
      console.log(`Données chargées : ${Object.keys(db.users).length} comptes, ${db.messages.length} messages`);
      if (dirty) flush();
      return;
    } catch (e) {
      loadError = e.message; console.error('Chargement impossible (' + i + ') :', e.message);
      await sleep(Math.min(3000 * i, 15000));
    }
  }
})();
